UPDATE products SET details = details || '{"facts":[{"criterion":"CALORIES","value":350,"unit":"kcal","basis":"PER_SERVING","source":"https://www.nongshimshop.com/product_info/101004264.jpg"},{"criterion":"SODIUM","value":1790,"unit":"mg","basis":"PER_SERVING","source":"https://www.nongshimshop.com/product_info/101004264.jpg"},{"criterion":"TOTAL_SUGAR","value":4,"unit":"g","basis":"PER_SERVING","source":"https://www.nongshimshop.com/product_info/101004264.jpg"},{"criterion":"SATURATED_FAT","value":1.4,"unit":"g","basis":"PER_SERVING","source":"https://www.nongshimshop.com/product_info/101004264.jpg"}],"evidence":[{"title":"농심 제품 영양표시","summary":"농심 공식몰에서 공개한 국내 봉지면 97 g의 영양표시입니다. 한 봉지에 나트륨 1,790 mg이 표시되어 있습니다.","source":"https://www.nongshimshop.com/product_info/101004264.jpg"},{"title":"WHO 성인 나트륨 섭취 권고","summary":"WHO는 성인에게 하루 나트륨 2,000 mg 미만을 권고합니다. 실제 섭취량은 먹은 양과 하루 동안의 다른 음식에 따라 달라집니다.","source":"https://www.who.int/news-room/fact-sheets/detail/sodium-reduction"}],"description":"농심 공식몰에 공개된 튀기지 않은 면을 사용한 봉지라면입니다. 국내 97 g 제품의 한 봉지 영양표시를 사용합니다."}'::jsonb WHERE id = 'shin-light';
