UPDATE products SET details = details || '{"evidence":[{"title":"WHO 유리당 섭취 권고","summary":"WHO는 유리당 섭취를 하루 총 에너지의 10% 미만으로 제한하도록 권고합니다. 제품 표의 총당류와 이 권고의 유리당은 정의가 다릅니다.","source":"https://www.who.int/news-room/fact-sheets/detail/healthy-diet"},{"title":"브랜드 관계","summary":"The Coca-Cola Company의 공식 브랜드 목록에서 상장사와의 관계를 확인할 수 있습니다.","source":"https://www.coca-colacompany.com/brands"},{"title":"착색료 · 카라멜색소","summary":"미국 제조사 성분표에 카라멜색소가 표시돼 있습니다. 색소 유형과 4-MEI 함량은 공개되지 않았습니다.","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/original/original-taste","topic":"caramel-color"}],"facts":[{"criterion":"CALORIES","value":140,"unit":"kcal","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/about-us/faq/how-much-sugar-is-in-coca-cola"},{"criterion":"TOTAL_SUGAR","value":39,"unit":"g","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/about-us/faq/how-much-sugar-is-in-coca-cola"},{"criterion":"CALORIES","value":39.45,"unit":"kcal","basis":"PER_100ML","source":"https://www.coca-cola.com/us/en/about-us/faq/how-much-sugar-is-in-coca-cola"},{"criterion":"TOTAL_SUGAR","value":10.99,"unit":"g","basis":"PER_100ML","source":"https://www.coca-cola.com/us/en/about-us/faq/how-much-sugar-is-in-coca-cola"},{"criterion":"AVOID_ASPARTAME","value":0,"unit":"flag","basis":"INGREDIENTS","source":"https://www.coca-cola.com/us/en/about-us/faq/what-is-aspartame"}]}'::jsonb WHERE id = 'coke-original';
UPDATE products SET details = details || '{"evidence":[{"title":"아스파탐 평가의 두 관점","summary":"IARC는 제한적인 인체 근거로 아스파탐을 그룹 2B로 분류했습니다. JECFA는 일일섭취허용량을 체중 1 kg당 0–40 mg으로 유지했습니다. 성분표만으로 개인의 노출량을 계산하기는 어렵습니다.","source":"https://www.iarc.who.int/news-events/aspartame-hazard-and-risk-assessment-results-released/"},{"title":"브랜드 관계","summary":"The Coca-Cola Company의 공식 브랜드 목록에서 상장사와의 관계를 확인할 수 있습니다.","source":"https://www.coca-colacompany.com/brands"},{"title":"보존료 · 안식향산칼륨","summary":"미국 제조사 성분표에 안식향산칼륨이 표시돼 있습니다. 제품의 벤젠 검출 여부는 이 표시로 확인할 수 없습니다.","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar","topic":"potassium-benzoate"},{"title":"착색료 · 카라멜색소","summary":"미국 제조사 성분표에 카라멜색소가 표시돼 있습니다. 색소 유형과 4-MEI 함량은 공개되지 않았습니다.","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar","topic":"caramel-color"}],"facts":[{"criterion":"CALORIES","value":0,"unit":"kcal","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"TOTAL_SUGAR","value":0,"unit":"g","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"SODIUM","value":40,"unit":"mg","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"ADDED_SUGAR","value":0,"unit":"g","basis":"PER_SERVING","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"CALORIES","value":0.0,"unit":"kcal","basis":"PER_100ML","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"TOTAL_SUGAR","value":0.0,"unit":"g","basis":"PER_100ML","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"SODIUM","value":11.27,"unit":"mg","basis":"PER_100ML","source":"https://www.coca-cola.com/us/en/brands/coca-cola/products/zero/zero-sugar"},{"criterion":"ADDED_SUGAR","value":0.0,"u